mapper.select:
SELECT ISTRADEFORM, SERIALNO, DT.FILENO, DT.APDT, DT.CUSTNO, DT.FUNDID, SUBAMT, SUBQUTY, CONTRACTSIGN, IBF_GET_PARAMNAME('SYSTEM','TRADESIGN',CONTRACTSIGN) CONTRACTSIGN_NAME, CONTRACTDEVOLVE, ISORIGINAL, FILED, REMARK, DT.INSERTTIMESTAMP, C.INVNM, FI.FUNDNM, DT.APKIND, VOICERECORD, RISKSIGN, DCL.INVPRTP FROM (SELECT D.ISTRADEFORM, D.SERIALNO, F.FILENO, ATT.APDT, ATT.CUSTNO, ATT.FUNDID, ATT.SUBAMT, ATT.SUBQUTY, D.CONTRACTSIGN, D.CONTRACTDEVOLVE, D.ISORIGINAL, D.FILED, D.REMARK, ATT.APKIND, ATT.INSERTTIMESTAMP, D.VOICERECORD, D.RISKSIGN FROM DS_TRADEDATA D, APPTRADEBLOTTER ATT, (SELECT DC.FILENO, A.CUSTNO FROM APPFDACBLOTTER A, DS_CUSTINFODATA DC WHERE A.SERIALNO = DC.APPSERIALNO AND A.APKIND = '001' GROUP BY DC.FILENO, A.APKIND, A.CUSTNO UNION ALL SELECT DC.FILENO, A.CUSTNO FROM H_APPFDACBLOTTER A, DS_CUSTINFODATA DC WHERE A.SERIALNO = DC.APPSERIALNO AND A.APKIND = '001' GROUP BY DC.FILENO, A.APKIND, A.CUSTNO) F WHERE D.APPSERIALNO = ATT.SERIALNO AND ATT.CUSTNO = F.CUSTNO(+) AND ATT.APPLYST NOT IN ('C', 'F') UNION ALL SELECT D.ISTRADEFORM, D.SERIALNO, F.FILENO, ATT.APDT, ATT.CUSTNO, ATT.FUNDID, ATT.SUBAMT, ATT.SUBQUTY, D.CONTRACTSIGN, D.CONTRACTDEVOLVE, D.ISORIGINAL, D.FILED, D.REMARK, ATT.APKIND, ATT.INSERTTIMESTAMP, D.VOICERECORD, D.RISKSIGN FROM DS_TRADEDATA D, H_APPTRADEBLOTTER ATT, (SELECT DC.FILENO, A.CUSTNO FROM H_APPFDACBLOTTER A, DS_CUSTINFODATA DC WHERE A.SERIALNO = DC.APPSERIALNO AND A.APKIND = '001' GROUP BY DC.FILENO, A.APKIND, A.CUSTNO) F WHERE D.APPSERIALNO = ATT.SERIALNO AND ATT.CUSTNO = F.CUSTNO(+)) DT, CUSTINFO C, FUNDINFO FI, DS_CUSTCLASSINFO DCL WHERE DT.CUSTNO = C.CUSTNO(+) AND DT.FUNDID = FI.FUNDID(+) AND DT.CUSTNO = DCL.CUSTNO(+)
AND APDT >= #{sp.startDate}
AND APDT <= #{sp.endDate}
AND FILENO LIKE '%'||#{sp.fileno}||'%'
AND FI.FUNDNM LIKE '%'||#{sp.fundnm}||'%'
AND INVNM LIKE '%'||#{sp.invnm}||'%'
AND CONTRACTSIGN = #{sp.contractsign}
AND CONTRACTDEVOLVE = #{sp.contractdevolve}
AND ISORIGINAL = #{sp.isoriginal}
AND FILED = #{sp.filed}
AND DT.CUSTNO = #{sp.custno}
AND DT.SUBAMT = #{sp.subamt}
AND SERIALNO = #{sp.serialno}
ORDER BY INSERTTIMESTAMP DESC

SELECT ISTRADEFORM, CASE WHEN ISTRADEFORM = 'Y' THEN '是' WHEN ISTRADEFORM = 'N' THEN '否' ELSE '' END AS ISTRADEFORM_NAME, SERIALNO, DT.FILENO, DT.APDT, DT.CUSTNO, DT.FUNDID, SUBAMT, SUBQUTY, CASE WHEN CONTRACTDEVOLVE = 'Y' THEN '是' WHEN CONTRACTDEVOLVE = 'N' THEN '否' ELSE '' END AS CONTRACTDEVOLVE_NAME, CASE WHEN RISKSIGN = '0' THEN '无需' WHEN RISKSIGN = '1' THEN '已签署' WHEN RISKSIGN = '2' THEN '未签署' ELSE '' END AS RISKSIGN_NAME, CONTRACTSIGN, IBF_GET_PARAMNAME('SYSTEM', 'TRADESIGN', CONTRACTSIGN) CONTRACTSIGN_NAME, CONTRACTDEVOLVE, CASE WHEN ISORIGINAL = 'Y' THEN '是' WHEN ISORIGINAL = 'N' THEN '否' ELSE '' END AS ISORIGINAL_NAME, ISORIGINAL, CASE WHEN FILED = 'Y' THEN '是' WHEN FILED = 'N' THEN '否' ELSE '' END AS FILED_NAME, FILED, REMARK, DT.INSERTTIMESTAMP, C.INVNM, FI.FUNDNM, DT.APKIND, VOICERECORD, RISKSIGN, CASE WHEN INVPRTP = '0' THEN '专业投资者' WHEN INVPRTP = '1' THEN '普通投资者' ELSE '' END AS INVPRTP_NAME, DCL.INVPRTP FROM (SELECT D.ISTRADEFORM, D.SERIALNO, F.FILENO, ATT.APDT, ATT.CUSTNO, ATT.FUNDID, ATT.SUBAMT, ATT.SUBQUTY, D.CONTRACTSIGN, D.CONTRACTDEVOLVE, D.ISORIGINAL, D.FILED, D.REMARK, ATT.APKIND, ATT.INSERTTIMESTAMP, D.VOICERECORD, D.RISKSIGN FROM DS_TRADEDATA D, APPTRADEBLOTTER ATT, (SELECT DC.FILENO, A.CUSTNO FROM APPFDACBLOTTER A, DS_CUSTINFODATA DC WHERE A.SERIALNO = DC.APPSERIALNO AND A.APKIND = '001' GROUP BY DC.FILENO, A.APKIND, A.CUSTNO UNION ALL SELECT DC.FILENO, A.CUSTNO FROM H_APPFDACBLOTTER A, DS_CUSTINFODATA DC WHERE A.SERIALNO = DC.APPSERIALNO AND A.APKIND = '001' GROUP BY DC.FILENO, A.APKIND, A.CUSTNO) F WHERE D.APPSERIALNO = ATT.SERIALNO AND ATT.CUSTNO = F.CUSTNO(+) AND ATT.APPLYST NOT IN ('C', 'F') UNION ALL SELECT D.ISTRADEFORM, D.SERIALNO, F.FILENO, ATT.APDT, ATT.CUSTNO, ATT.FUNDID, ATT.SUBAMT, ATT.SUBQUTY, D.CONTRACTSIGN, D.CONTRACTDEVOLVE, D.ISORIGINAL, D.FILED, D.REMARK, ATT.APKIND, ATT.INSERTTIMESTAMP, D.VOICERECORD, D.RISKSIGN FROM DS_TRADEDATA D, H_APPTRADEBLOTTER ATT, (SELECT DC.FILENO, A.CUSTNO FROM H_APPFDACBLOTTER A, DS_CUSTINFODATA DC WHERE A.SERIALNO = DC.APPSERIALNO AND A.APKIND = '001' GROUP BY DC.FILENO, A.APKIND, A.CUSTNO) F WHERE D.APPSERIALNO = ATT.SERIALNO AND ATT.CUSTNO = F.CUSTNO(+)) DT, CUSTINFO C, FUNDINFO FI, DS_CUSTCLASSINFO DCL WHERE DT.CUSTNO = C.CUSTNO(+) AND DT.FUNDID = FI.FUNDID(+) AND DT.CUSTNO = DCL.CUSTNO(+)
AND APDT >= #{sp.startDate}
AND APDT <= #{sp.endDate}
AND FILENO LIKE '%'||#{sp.fileno}||'%'
AND FI.FUNDNM LIKE '%'||#{sp.fundnm}||'%'
AND INVNM LIKE '%'||#{sp.invnm}||'%'
AND CONTRACTSIGN = #{sp.contractsign}
AND CONTRACTDEVOLVE = #{sp.contractdevolve}
AND ISORIGINAL = #{sp.isoriginal}
AND FILED = #{sp.filed}
AND DT.CUSTNO = #{sp.custno}
AND DT.SUBAMT = #{sp.subamt}
AND SERIALNO = #{sp.serialno}
ORDER BY INSERTTIMESTAMP DESC

SELECT COUNT(*) FROM (SELECT D.ISTRADEFORM, D.SERIALNO, F.FILENO, ATT.APDT, ATT.CUSTNO, ATT.FUNDID, ATT.SUBAMT, ATT.SUBQUTY, D.CONTRACTSIGN, D.CONTRACTDEVOLVE, D.ISORIGINAL, D.FILED, D.REMARK, ATT.APKIND, ATT.INSERTTIMESTAMP, D.VOICERECORD, D.RISKSIGN FROM DS_TRADEDATA D, APPTRADEBLOTTER ATT, (SELECT DC.FILENO, A.CUSTNO FROM APPFDACBLOTTER A, DS_CUSTINFODATA DC WHERE A.SERIALNO = DC.APPSERIALNO AND A.APKIND = '001' GROUP BY DC.FILENO, A.APKIND, A.CUSTNO UNION ALL SELECT DC.FILENO, A.CUSTNO FROM H_APPFDACBLOTTER A, DS_CUSTINFODATA DC WHERE A.SERIALNO = DC.APPSERIALNO AND A.APKIND = '001' GROUP BY DC.FILENO, A.APKIND, A.CUSTNO) F WHERE D.APPSERIALNO = ATT.SERIALNO AND ATT.CUSTNO = F.CUSTNO(+) AND ATT.APPLYST NOT IN ('C', 'F') UNION ALL SELECT D.ISTRADEFORM, D.SERIALNO, F.FILENO, ATT.APDT, ATT.CUSTNO, ATT.FUNDID, ATT.SUBAMT, ATT.SUBQUTY, D.CONTRACTSIGN, D.CONTRACTDEVOLVE, D.ISORIGINAL, D.FILED, D.REMARK, ATT.APKIND, ATT.INSERTTIMESTAMP, D.VOICERECORD, D.RISKSIGN FROM DS_TRADEDATA D, H_APPTRADEBLOTTER ATT, (SELECT DC.FILENO, A.CUSTNO FROM H_APPFDACBLOTTER A, DS_CUSTINFODATA DC WHERE A.SERIALNO = DC.APPSERIALNO AND A.APKIND = '001' GROUP BY DC.FILENO, A.APKIND, A.CUSTNO) F WHERE D.APPSERIALNO = ATT.SERIALNO AND ATT.CUSTNO = F.CUSTNO(+)) DT, CUSTINFO C, FUNDINFO FI, DS_CUSTCLASSINFO DCL WHERE DT.CUSTNO = C.CUSTNO(+) AND DT.FUNDID = FI.FUNDID(+) AND DT.CUSTNO = DCL.CUSTNO(+)
AND APDT >= #{sp.startDate}
AND APDT <= #{sp.endDate}
AND FI.FUNDNM LIKE '%'||#{sp.fileno}||'%'
AND FILENO LIKE '%'||#{sp.fundnm}||'%'
AND INVNM LIKE '%'||#{sp.invnm}||'%'
AND CONTRACTSIGN = #{sp.contractsign}
AND CONTRACTDEVOLVE = #{sp.contractdevolve}
AND ISORIGINAL = #{sp.isoriginal}
AND FILED = #{sp.filed}
AND DT.CUSTNO = #{sp.custno}
AND DT.SUBAMT = #{sp.subamt}
